import json
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import TimeoutException

def login_test(portal_url, selectors, test_data):
    driver = webdriver.Chrome()  # Or any other desired browser
    driver.get(portal_url)

    test_results = []

    for credentials, result_type in test_data.items():
        try:
            username_field = driver.find_element(By.ID, selectors["username_field"])
            password_field = driver.find_element(By.ID, selectors["password_field"])
            login_button = driver.find_element(By.CLASS_NAME, selectors["login_button"])

            username_field.send_keys(result_data["user"])
            password_field.send_keys(result_data["pass"])
            login_button.click()

            # Wait for dashboard indicator to appear
            try:
                WebDriverWait(driver, 10).until(
                    EC.presence_of_element_located((By.ID, selectors["dashboard_indicator"]))
                )
                dashboard_indicator = driver.find_element(By.ID, selectors["dashboard_indicator"])
                dashboard_text = dashboard_indicator.text
                if "Welcome, " + result_data["user"] in dashboard_text:
                    test_results.append({
                        "test_name": f"Login with {result_data['user']} and {result_data['pass']}",
                        "status": "pass",
                        "result": "Successful login",
                        "details": dashboard_text
                    })
                else:
                    test_results.append({
                        "test_name": f"Login with {result_data['user']} and {result_data['pass']}",
                        "status": "fail",
                        "result": "Login failed - Dashboard indicator mismatch",
                        "details": dashboard_text
                    })
            except TimeoutException:
                test_results.append({
                    "test_name": f"Login with {result_data['user']} and {result_data['pass']}",
                    "status": "fail",
                    "result": "Login failed - Timeout waiting for dashboard indicator",
                    "details": ""
                })
        except Exception as e:
            test_results.append({
                "test_name": f"Login with {result_data['user']} and {result_data['pass']}",
                "status": "fail",
                "result": f"Login failed - {str(e)}",
                "details": ""
            })

    driver.quit()

    report = {
        "test_results": test_results
    }

    return json.dumps(report, indent=2)

if __name__ == '__main__':
    context = {
      "portal_url": "https://admin.example.com/login",
      "selectors": {
        "username_field": "id='admin-user'",
        "password_field": "id='admin-pass'",
        "login_button": "class='btn-login'",
        "dashboard_indicator": "id='welcome-msg'"
      },
      "test_data": {
        "valid_creds": {
          "user": "admin",
          "pass": "secure123"
        },
        "invalid_creds": {
          "user": "hacker",
          "pass": "wrong"
        }
      }
    }

    report = login_test(context["portal_url"], context["selectors"], context["test_data"])
    print(report)
```
